// Listen starts the IMAP server listening on the configured address.
// It returns an error if the server fails to start listening.
func (s *Server) Listen() error {
	l, err := net.Listen("tcp", s.Addr)
	if err != nil {
		return fmt.Errorf("imap: failed to listen on %s: %w", s.Addr, err)
	}
	s.listeners = append(s.listeners, l)
	return nil
}

// ListenAndServe listens on the server's address and then serves requests
// indefinitely. It returns an error if the server fails to start listening.
func (s *Server) ListenAndServe() error {
	if err := s.Listen(); err != nil {
		return err
	}
	return s.Serve()
}

// Serve accepts incoming connections and handles them.
// This method blocks until the server is stopped.
func (s *Server) Serve() error {
	for _, l := range s.listeners {
		go s.acceptLoop(l)
	}

