// Listen starts the IMAP server listening on the configured address.
// This method does not block.
func (s *Server) Listen() error {
	l, err := net.Listen("tcp", s.Addr)
	if err != nil {
		return fmt.Errorf("failed to listen on %s: %w", s.Addr, err)
	}
	s.listeners = append(s.listeners, l)
	return nil
}

// Serve accepts incoming connections and handles them.
// This method blocks indefinitely.
func (s *Server) Serve() error {
	if len(s.listeners) == 0 {
		return fmt.Errorf("server is not listening, call Listen() first")
	}

	for _, l := range s.listeners {
		go s.accept(l)
	}

	// This goroutine will block forever, waiting for connections.
	// The actual serving of clients is handled in separate goroutines.
	select {}
}

