	w.Header().Set("Content-Type", "application/json")
	var user User
	err := json.NewDecoder(r.Body).Decode(&user)
	if err != nil {
		resp := Resp{Code: -1, Message: "invalid request"}
		json.NewEncoder(w).Encode(resp)
		return
	}

	u, ok := checkUser(user.Username, user.Password)
	if !ok {
		resp := Resp{Code: -1, Message: "invalid username or password"}
		json.NewEncoder(w).Encode(resp)
		return
	}

	session, err := store.Get(r, "session")
	if err != nil {
		resp := Resp{Code: -1, Message: "session error"}
		json.NewEncoder(w).Encode(resp)
		return
	}
	session.Values["username"] = u.Username
	session.Save(r, w)

	resp := Resp{Code: 0, Message: "login success"}

