func (r *Reader) NextFile() (name string, err error) {
	// Initialize unread
	if r.unread == nil {
		r.unread = r.Files()[:]
	}

	// Close previous file
	if r.rc != nil {
		r.rc.Close() // Read-only
	}

	if len(r.unread) == 0 {
		return "", io.EOF
	}

	// Open and return next unread
	f := r.unread[0]
	name, r.unread = f.Name, r.unread[1:]
	r.rc, err = f.Open()
	if err != nil {
		return "", err
	}
	return name, nil
}

