// Type represents an ABI type.
type Type struct {
	T          reflect.Kind
	String     string
	Tuple      []*Type
	Array      *Type
	ArrayLen   int
	Components []*Type // For structs
}

// NewType creates a new ABI type.
func NewType(s string) (*Type, error) {
	return parseType(s)
}

// IsDynamic checks if the type is dynamic.
func (t *Type) IsDynamic() bool {
	switch t.T {
	case reflect.Slice, reflect.Array:
		if t.ArrayLen == -1 {
			return true
		}
		return t.Array.IsDynamic()
	case reflect.String:
		return true
	case reflect.Struct:
		for _, c := range t.Components {
			if c.IsDynamic() {
				return true
			}
		}
		return false
	default:
		return false
	}
}

